// Generator for the CoolerMaster module device table.
// Usage: node scripts/openrgb/port-coolermaster-devices.mjs <openrgb-root> <commit>
// Reads CoolerMasterControllerDetect.cpp and regenerates
// modules/coolermaster/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'CoolerMasterController');
const detect = fs.readFileSync(path.join(family, 'CoolerMasterControllerDetect.cpp'), 'utf8');
const headerText = fs
  .readdirSync(family, { recursive: true })
  .filter((f) => /\.(cpp|h)$/.test(f))
  .map((f) => fs.readFileSync(path.join(family, f), 'utf8'))
  .join('\n');
const constants = Object.fromEntries(
  [...headerText.matchAll(/#define\s+([A-Z][A-Z0-9_]*)\s+0x([0-9A-Fa-f]+)/g)].map((m) => [
    m[1],
    Number.parseInt(m[2], 16),
  ]),
);
if (constants.CM_VID == null && constants.COOLERMASTER_VID == null) {
  // keep going: some rows use inline hex
}
const n = (s) => {
  const t = s.trim();
  if (t in constants) return constants[t];
  if (/^0x[0-9A-Fa-f]+$/.test(t)) return Number.parseInt(t, 16);
  if (/^\d+$/.test(t)) return Number.parseInt(t, 10);
  throw new Error(`unresolved constant ${t}`);
};

const rows = [];
for (const m of detect.matchAll(
  /REGISTER_HID_DETECTOR[A-Z_]*\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*([A-Z][A-Z0-9_]+)\s*,\s*([A-Z][A-Z0-9_]+)\s*(?:,\s*([^)]*)\))?/g,
)) {
  const vid = n(m[3]);
  const pid = n(m[4]);
  const args = (m[5] ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const variant = m[0].startsWith('REGISTER_HID_DETECTOR_IPU')
    ? 'IPU'
    : m[0].startsWith('REGISTER_HID_DETECTOR_IP')
      ? 'IP'
      : m[0].startsWith('REGISTER_HID_DETECTOR_PU')
        ? 'PU'
        : 'I';
  const anyPage = 65535;
  let argRows = [];
  if (variant === 'IPU' && args.length === 3) {
    argRows = [{ interface: n(args[0]), usagePage: n(args[1]), usage: n(args[2]) }];
  } else if (variant === 'IP' && args.length === 2) {
    argRows = [{ interface: n(args[0]), usagePage: n(args[1]), usage: 0 }];
  } else if (variant === 'PU' && args.length === 2) {
    // _PU rows carry (usage page, usage) and match any interface
    argRows = [{ interface: 255, usagePage: n(args[0]), usage: n(args[1]) }];
  } else if (variant === 'I' && args.length === 1) {
    argRows = [{ interface: n(args[0]), usagePage: anyPage, usage: 0 }];
  } else {
    throw new Error(`unexpected args ${JSON.stringify(args)} for ${variant} in row ${m[1]}`);
  }
  for (const a of argRows) {
    rows.push({ name: m[1], handler: m[2], vid, pid, ...a });
  }
}
if (rows.length !== 38) throw new Error(`expected 38 detector rows, got ${rows.length}`);

const out = path.join(process.cwd(), 'modules', 'coolermaster', 'src', 'devices_table.rs');
fs.mkdirSync(path.dirname(out), { recursive: true });
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-coolermaster-devices.mjs from OpenRGB ${commit}; do not edit.`,
  'use crate::table::Detector;',
  '',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map((d) =>
    `    Detector { name: ${JSON.stringify(d.name)}, handler: ${JSON.stringify(d.handler)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, interface: ${d.interface}, usage_page: 0x${d.usagePage.toString(16)}, usage: ${d.usage}, },
`,
  ),
  '];',
  '',
];
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${rows.length} Cooler Master HID detectors`);